], \"page_id\": 8}], \"content\": \"\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [584, 319, 978, 369], \"page_id\": 9}], \"content\": \"Table of Contents\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [1217, 467, 1310, 510], \"page_id\": 9}], \"content\": \"Page\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [272, 517, 1296, 1676], \"page_id\": 9}], \"content\": \"<table><tr><td>Introduction</td><td>1</td></tr><tr><td colspan=\\\"2\\\">Receipts and Expenditures</td></tr><tr><td>First Six Months of Fiscal Years 1934-39</td><td>3</td></tr><tr><td>Calendar Years, 1935-38</td><td>3</td></tr><tr><td>Fiscal Years, 1932-33</td><td>4-5</td></tr><tr><td>Social Security Acts</td><td>5-6</td></tr><tr><td>Railroad Retirement Act</td><td>6</td></tr><tr><td>Cash Income and Outgo</td><td>7-8</td></tr><tr><td colspan=\\\"2\\\">General Fund and Public Debt</td></tr><tr><td>Composition of General Fund, 1933-38</td><td>10</td></tr><tr><td>Public Debt, June 30 and December 31, 1938</td><td>10</td></tr><tr><td>Holdings of Government Obligations, 1936-38</td><td>11</td></tr><tr><td>Composition of Public Debt</td><td>12</td></tr><tr><td>Major Financing Operations, 1933-38</td><td>13-14</td></tr><tr><td>Computed Interest, Comparative Yields</td><td>15</td></tr><tr><td>Holdings by U. S. Trust Accounts, etc.</td><td>16</td></tr><tr><td colspan=\\\"2\\\">Contingent Liabilities</td></tr><tr><td>U. S. Corporations, Credit Agencies</td><td>18</td></tr><tr><td>U. S. Proprietary Interest</td><td>18</td></tr><tr><td colspan=\\\"2\\\">Capital Movements</td></tr><tr><td>Summary Table</td><td>20</td></tr><tr><td>Short-term Foreign Assets and Liabilities</td><td>21-22</td></tr><tr><td>Security Transactions, etc.</td><td>23-24</td></tr><tr><td>Foreign Exchange Transactions</td><td>25-26</td></tr><tr><td colspan=\\\"2\\\">Other Monetary Data</td></tr><tr><td>Gold, Silver Stocks</td><td>29-30</td></tr><tr><td>Silver Production, Movements</td><td>30-31</td></tr><tr><td>Foreign Exchange Data</td><td>33</td></tr><tr><td colspan=\\\"2\\\">Miscellaneous</td></tr><tr><td>Commodities Imported under Quotas</td><td>35</td></tr><tr><td>Law Enforcement Statistics</td><td>36</td></tr></table>\", \"description\": null, \"id\": 2, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [323, 430, 1182, 455], \"page_id\": 11}], \"content\": \"BULLETIN OF THE TREASURY DEPARTMENT\", \"description\": null, \"id\": 0, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [628, 578, 899, 601], \"page_id\": 11}], \"content\": \"INTRODUCTION\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [195, 678, 1317, 849], \"page_id\": 11}], \"content\": \"This Bulletin contains statistics of the United States Government transactions and other information gathered by the Treasury Department. It is the intention to issue similar Bulletins monthly and to incorporate in them information additional to that which is included in this first issue.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [193, 892, 1304, 1100], \"page_id\": 11}], \"content\": \"The purpose of the Bulletin is to extend knowledge of the public finances, monetary developments and activities of the Treasury Department by making information available in a more compact and usable form. The material herein contained supplements or recapitulates data contained in the Daily Treasury Statement and other publications and press releases of the Treasury Department.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [189, 1141, 1336, 1280], \"page_id\": 11}], \"content\": \"Only a limited number of copies is being prepared, for the present distribution will be restricted in the main to periodical publications desiring to make use of the material and to public officers. Other requests may be filled only to the extent of the limited supply.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [189, 1321, 1303, 1418], \"page_id\": 11}], \"content\": \"I shall be glad to receive and to give careful consideration to suggestions for improving the Bulletin so as to make it serve its purpose more adequately.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1473, 1313, 1535], \"page_id\": 11}], \"content\": \"Henry Morgenthau, Jr. Secretary of the Treasury.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [724, 1951, 787, 1974], \"page_id\": 11}], \"content\": \"-1-\", \"description\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [154, 409, 1352, 1611], \"page_id\": 12}], \"content\": \"\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [331, 984, 1168, 1020], \"page_id\": 13}], \"content\": \"RECEIPTS AND EXPENDITURES\", \"description\": null, \"id\": 0, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [715, 1218, 782, 1245], \"page_id\": 13}], \"content\": \"-2-\", \"description\": null, \"id\": 1, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [282, 121, 503, 153], \"page_id\": 15}], \"content\": \"Summary Tables\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [259, 159, 505, 196], \"page_id\": 15}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [261, 196, 496, 228], \"page_id\": 15}], \"content\": \"RECEIPTS AND EXPENDITURES\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [86, 235, 694, 421], \"page_id\": 15}], \"content\": \"<table><tr><th rowspan=\\\"2\\\"></th><th colspan=\\\"6\\\">First 6 months fiscal year</th><th rowspan=\\\"2\\\">Change '38 -'39</th></tr><tr><th>1934</th><th>1935</th><th>1936</th><th>1937</th><th>1938</th><th>1939</th></tr><tr><td>Receipts.....</td><td>1,469</td><td>1,845</td>